<?php foreach($products as $p): ?>
<article class="product-card"><a class="product-image" href="/?page=product&amp;id=<?= $p['id'] ?>"><img src="/assets/images/<?= e(imageFile($p['image'])) ?>" alt="<?= e($p['name']) ?>" loading="lazy"><span class="product-label"><?= $p['stock']?'במלאי':'אזל מהמלאי' ?></span></a><div class="product-content"><a href="/?page=product&amp;id=<?= $p['id'] ?>"><h3><?= e($p['name']) ?></h3></a><p><?= e($p['short_description']) ?></p><div class="product-bottom"><strong><?= money((int)$p['price_cents']) ?></strong><form method="post"><?= csrf() ?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><input type="hidden" name="quantity" value="1"><button class="add-button" aria-label="הוספת <?= e($p['name']) ?> לסל" <?= !$p['stock']?'disabled':'' ?>>+</button></form></div></div></article>
<?php endforeach ?>
